import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  Modal,
  Alert,
  Animated,
  Dimensions,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useApp } from '../context/AppContext';

const { width, height } = Dimensions.get('window');

// Character data (same as in GachaComponents.js)
const CHARACTERS = {
  common: [
    { id: 'c1', name: 'Fitness Rookie', rarity: 'common', image: '🏃‍♂️', stats: { strength: 10, endurance: 8, motivation: 12 } },
    { id: 'c2', name: 'Gym Rat', rarity: 'common', image: '💪', stats: { strength: 12, endurance: 10, motivation: 8 } },
    { id: 'c3', name: 'Cardio Queen', rarity: 'common', image: '🏃‍♀️', stats: { strength: 8, endurance: 15, motivation: 10 } },
  ],
  rare: [
    { id: 'r1', name: 'Iron Warrior', rarity: 'rare', image: '⚔️', stats: { strength: 18, endurance: 15, motivation: 12 } },
    { id: 'r2', name: 'Endurance Master', rarity: 'rare', image: '🏋️‍♂️', stats: { strength: 15, endurance: 20, motivation: 15 } },
    { id: 'r3', name: 'Motivation Guru', rarity: 'rare', image: '🌟', stats: { strength: 12, endurance: 12, motivation: 25 } },
  ],
  epic: [
    { id: 'e1', name: 'Legendary Lifter', rarity: 'epic', image: '👑', stats: { strength: 25, endurance: 20, motivation: 18 } },
    { id: 'e2', name: 'Unstoppable Force', rarity: 'epic', image: '🔥', stats: { strength: 30, endurance: 25, motivation: 20 } },
  ],
  legendary: [
    { id: 'l1', name: 'Fitness Deity', rarity: 'legendary', image: '⚡', stats: { strength: 40, endurance: 35, motivation: 30 } },
    { id: 'l2', name: 'Ultimate Champion', rarity: 'legendary', image: '🏆', stats: { strength: 35, endurance: 40, motivation: 35 } },
  ],
};

const RARITY_COLORS = {
  common: '#8B8B8B',
  rare: '#4A90E2',
  epic: '#9B59B6',
  legendary: '#F39C12',
};

export const WorkoutVerificationWidget = ({ workout, onVerificationComplete }) => {
  const { userStats, updateUserStats } = useApp();
  const [showVerification, setShowVerification] = useState(false);
  const [verificationStep, setVerificationStep] = useState(0);
  const [gemsEarned, setGemsEarned] = useState(0);
  const [characterEarned, setCharacterEarned] = useState(null);
  const [animation] = useState(new Animated.Value(0));

  const calculateWorkoutRewards = (workout) => {
    let gems = 0;
    let characterChance = 0;

    // Base gems for completing workout
    gems += 25;

    // Bonus gems for workout duration
    if (workout.duration) {
      gems += Math.floor(workout.duration / 5); // 1 gem per 5 minutes
    }

    // Bonus gems for number of exercises
    if (workout.exercises) {
      gems += workout.exercises.length * 2; // 2 gems per exercise
    }

    // Bonus gems for high rating
    if (workout.ratings?.workoutRating >= 8) {
      gems += 15;
    }

    // Character pull chance based on workout quality
    if (workout.ratings?.workoutRating >= 9) {
      characterChance = 0.3; // 30% chance for 9+ rating
    } else if (workout.ratings?.workoutRating >= 7) {
      characterChance = 0.15; // 15% chance for 7+ rating
    }

    return { gems, characterChance };
  };

  const performCharacterPull = () => {
    const random = Math.random();
    if (random > 0.85) return 'legendary';
    if (random > 0.7) return 'epic';
    if (random > 0.4) return 'rare';
    return 'common';
  };

  const handleVerificationComplete = async () => {
    const rewards = calculateWorkoutRewards(workout);
    let earnedGems = rewards.gems;
    let earnedCharacter = null;

    // Check for character pull
    if (Math.random() < rewards.characterChance) {
      const rarity = performCharacterPull();
      const charactersOfRarity = CHARACTERS[rarity];
      earnedCharacter = charactersOfRarity[Math.floor(Math.random() * charactersOfRarity.length)];
    }

    // Update user stats
    const newGems = (userStats.gems || 0) + earnedGems;
    const newCharacters = [...(userStats.characters || []), ...(earnedCharacter ? [earnedCharacter.id] : [])];

    await updateUserStats({
      ...userStats,
      gems: newGems,
      characters: newCharacters,
    });

    setGemsEarned(earnedGems);
    setCharacterEarned(earnedCharacter);
    setShowVerification(true);
  };

  const confirmRewards = () => {
    setShowVerification(false);
    setVerificationStep(0);
    setGemsEarned(0);
    setCharacterEarned(null);
    onVerificationComplete();
  };

  return (
    <View style={styles.container}>
      <TouchableOpacity style={styles.verificationButton} onPress={handleVerificationComplete}>
        <Ionicons name="checkmark-circle" size={24} color="#007AFF" />
        <Text style={styles.verificationButtonText}>Verify Workout & Get Rewards</Text>
      </TouchableOpacity>

      <Modal visible={showVerification} transparent animationType="fade">
        <View style={styles.modalOverlay}>
          <View style={styles.rewardModal}>
            <Text style={styles.rewardTitle}>🎉 Workout Verified!</Text>
            
            <View style={styles.rewardsContainer}>
              <View style={styles.gemReward}>
                <Ionicons name="diamond" size={32} color="#F39C12" />
                <Text style={styles.gemRewardText}>+{gemsEarned} Gems</Text>
              </View>

              {characterEarned && (
                <View style={[styles.characterReward, { borderColor: RARITY_COLORS[characterEarned.rarity] }]}>
                  <Text style={styles.characterImage}>{characterEarned.image}</Text>
                  <Text style={styles.characterName}>{characterEarned.name}</Text>
                  <Text style={[styles.characterRarity, { color: RARITY_COLORS[characterEarned.rarity] }]}>
                    {characterEarned.rarity.toUpperCase()}
                  </Text>
                </View>
              )}
            </View>

            <TouchableOpacity style={styles.confirmButton} onPress={confirmRewards}>
              <Text style={styles.confirmButtonText}>Collect Rewards</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </View>
  );
};

export const CharacterCollectionWidget = ({ navigation }) => {
  const { userStats } = useApp();
  const userCharacters = userStats.characters || [];
  const allCharacters = Object.values(CHARACTERS).flat();
  const collectionProgress = (userCharacters.length / allCharacters.length) * 100;

  return (
    <TouchableOpacity
      style={styles.collectionWidget}
      onPress={() => navigation.navigate('CharacterCollection')}
    >
      <View style={styles.collectionHeader}>
        <Text style={styles.collectionTitle}>Character Collection</Text>
        <Ionicons name="chevron-forward" size={20} color="#007AFF" />
      </View>
      
      <View style={styles.collectionStats}>
        <Text style={styles.collectionCount}>
          {userCharacters.length} / {allCharacters.length}
        </Text>
        <View style={styles.progressBar}>
          <View style={[styles.progressFill, { width: `${collectionProgress}%` }]} />
        </View>
      </View>

      <View style={styles.recentCharacters}>
        {userCharacters.slice(0, 3).map((characterId, index) => {
          const character = allCharacters.find(c => c.id === characterId);
          if (!character) return null;
          
          return (
            <View key={characterId} style={styles.characterPreview}>
              <Text style={styles.characterPreviewImage}>{character.image}</Text>
            </View>
          );
        })}
        {userCharacters.length === 0 && (
          <Text style={styles.noCharactersText}>No characters yet</Text>
        )}
      </View>
    </TouchableOpacity>
  );
};

