export const CharacterBonusWidget = () => {
  const { userStats } = useApp();
  const userCharacters = userStats.characters || [];
  const allCharacters = Object.values(CHARACTERS).flat();
  
  const activeCharacters = userCharacters
    .map(id => allCharacters.find(c => c.id === id))
    .filter(Boolean);

  const totalBonus = activeCharacters.reduce((bonus, character) => {
    return {
      strength: bonus.strength + character.stats.strength,
      endurance: bonus.endurance + character.stats.endurance,
      motivation: bonus.motivation + character.stats.motivation,
    };
  }, { strength: 0, endurance: 0, motivation: 0 });

  return (
    <View style={styles.bonusWidget}>
      <Text style={styles.bonusTitle}>Character Bonuses</Text>
      
      {activeCharacters.length > 0 ? (
        <View style={styles.bonusStats}>
          <View style={styles.bonusStat}>
            <Text style={styles.bonusStatLabel}>Strength</Text>
            <Text style={styles.bonusStatValue}>+{totalBonus.strength}</Text>
          </View>
          <View style={styles.bonusStat}>
            <Text style={styles.bonusStatLabel}>Endurance</Text>
            <Text style={styles.bonusStatValue}>+{totalBonus.endurance}</Text>
          </View>
          <View style={styles.bonusStat}>
            <Text style={styles.bonusStatLabel}>Motivation</Text>
            <Text style={styles.bonusStatValue}>+{totalBonus.motivation}</Text>
          </View>
        </View>
      ) : (
        <Text style={styles.noBonusText}>No characters to provide bonuses</Text>
      )}
    </View>
  );
};

